def parser(log: str) -> dict[str, str]:
    import re
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}
    priority = {"pass": 0, "skip": 1, "fail": 2}

    def update(name: str, status: str) -> None:
        if not name:
            return
        cur = results.get(name)
        if cur is None or priority[status] > priority[cur]:
            results[name] = status

    def parse_xml(xml_text: str) -> bool:
        try:
            root = ET.fromstring(xml_text)
        except ET.ParseError:
            return False
        for case in root.findall(".//testcase"):
            name = case.get("name") or case.get("classname") or ""
            if not name:
                continue
            status = "pass"
            if case.find("skipped") is not None:
                status = "skip"
            if case.find("failure") is not None or case.find("error") is not None:
                status = "fail"
            update(name, status)
        return True

    # Parse XML segments if possible.
    segments = re.findall(r"<testsuites?[\s\S]*?</testsuites?>", log)
    if not segments:
        segments = re.findall(r"<testsuite[\s\S]*?</testsuite>", log)
    for seg in segments:
        parse_xml(seg)

    # Try a single XML document if segments did not parse.
    if not results:
        start = log.find("<?xml")
        if start != -1:
            end = log.rfind("</testsuites>")
            end_tag = "</testsuites>"
            if end == -1:
                end = log.rfind("</testsuite>")
                end_tag = "</testsuite>"
            if end != -1:
                parse_xml(log[start : end + len(end_tag)])

    # Regex fallback for truncated/malformed XML.
    for m in re.finditer(
        r"<testcase\b[^>]*>(.*?)</testcase>", log, re.IGNORECASE | re.DOTALL
    ):
        full_tag = m.group(0)
        start_tag = re.match(r"<testcase\b[^>]*>", full_tag, re.IGNORECASE)
        if not start_tag:
            continue
        attrs = dict(
            re.findall(r'(\w+)\s*=\s*["\'](.*?)["\']', start_tag.group(0))
        )
        name = attrs.get("name") or attrs.get("classname") or ""
        body = m.group(1)
        status = "pass"
        if re.search(r"<\s*(failure|error)\b", body, re.IGNORECASE):
            status = "fail"
        elif re.search(r"<\s*skipped\b", body, re.IGNORECASE):
            status = "skip"
        elif attrs.get("status", "").lower() in ("notrun", "skipped", "skip", "disabled"):
            status = "skip"
        update(name, status)

    for m in re.finditer(r"<testcase\b[^>]*/>", log, re.IGNORECASE):
        tag = m.group(0)
        attrs = dict(re.findall(r'(\w+)\s*=\s*["\'](.*?)["\']', tag))
        name = attrs.get("name") or attrs.get("classname") or ""
        status = "pass"
        if attrs.get("status", "").lower() in ("notrun", "skipped", "skip", "disabled"):
            status = "skip"
        update(name, status)

    return results
